/** Whether we have a brand mark for `provider` (the emoji Mercator globe counts). */
export function hasProviderLogo(provider: string) {
  return provider === "mercator" || provider in LOGOS;
}

/** The provider's brand mark, or null when there is none. */
export function ProviderLogo({ provider, className = "size-8 shrink-0" }: { provider: string; className?: string }) {
  if (provider === "mercator") {
    return (
      <span className={cn(className, "inline-flex items-center justify-center text-2xl")} aria-hidden="true">
        🌐
      </span>
    );
  }
  const logo = LOGOS[provider];
  if (!logo) return null;
  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      viewBox={logo.viewBox}
      className={className}
      aria-hidden="true"
      focusable="false"
      data-provider-logo={provider}
    >
      {logo.paths.map(([fill, d]) => (
        <path key={d} fill={fill} d={d} />
      ))}
    </svg>
  );
}

/** The 40px tile used on Integrations cards: the logo, else the provider's first two letters. */
export function ProviderTile({ provider, fallback = true }: { provider: string; fallback?: boolean }) {
  if (hasProviderLogo(provider)) {
    return (
      <span className="flex size-10 shrink-0 items-center justify-center rounded-lg bg-muted text-heading">
        <ProviderLogo provider={provider} />
      </span>
    );
  }
  if (!fallback) return null;
  return (
    <span
      className="flex size-10 shrink-0 items-center justify-center rounded-lg bg-muted text-xs font-semibold tracking-wide text-foreground uppercase"
      aria-hidden="true"
    >
      {provider.slice(0, 2)}
    </span>
  );
}
